C++Python <pre><code>/**
 * Bitmask DP — Travelling Salesman Problem (Held-Karp).
 *
 * Minimum cost of a Hamiltonian cycle that starts and ends at node 0,
 * visiting every node exactly once. `dist` is an n x n cost matrix.
 *   time:  O(2^n * n^2)
 *   space: O(2^n * n)
 *
 * State: dp[mask][u] = min cost of a path that started at 0, visited exactly
 * the nodes in `mask`, and currently sits at `u`.
 */
#include &lt;vector&gt;
#include &lt;algorithm&gt;
using namespace std;

const long long INF = 1e18;

long long tsp(const vector&lt;vector&lt;long long&gt;&gt;&amp; dist) {
    int n = dist.size();
    vector&lt;vector&lt;long long&gt;&gt; dp(1 &lt;&lt; n, vector&lt;long long&gt;(n, INF));
    dp[1][0] = 0;                                  // start at node 0

    for (int mask = 1; mask &lt; (1 &lt;&lt; n); mask++) {
        for (int u = 0; u &lt; n; u++) {
            if (dp[mask][u] == INF || !(mask &amp; (1 &lt;&lt; u))) continue;
            for (int v = 0; v &lt; n; v++) {
                if (mask &amp; (1 &lt;&lt; v)) continue;     // v already visited
                int nmask = mask | (1 &lt;&lt; v);
                dp[nmask][v] = min(dp[nmask][v], dp[mask][u] + dist[u][v]);
            }
        }
    }

    long long ans = INF;
    int full = (1 &lt;&lt; n) - 1;
    for (int u = 0; u &lt; n; u++)
        ans = min(ans, dp[full][u] + dist[u][0]);  // close the cycle back to 0
    return ans;
}
</code></pre> <pre><code>"""Bitmask DP — Travelling Salesman Problem (Held-Karp).

Minimum cost of a Hamiltonian cycle that starts and ends at node 0, visiting
every node exactly once. `dist` is an n x n cost matrix.
    time:  O(2^n * n^2)
    space: O(2^n * n)

State: dp[mask][u] = min cost of a path that started at 0, visited exactly the
nodes in `mask`, and currently sits at `u`.
"""
INF = float("inf")


def tsp(dist):
    n = len(dist)
    dp = [[INF] * n for _ in range(1 &lt;&lt; n)]
    dp[1][0] = 0                                   # start at node 0

    for mask in range(1, 1 &lt;&lt; n):
        for u in range(n):
            if dp[mask][u] == INF or not (mask &amp; (1 &lt;&lt; u)):
                continue
            for v in range(n):
                if mask &amp; (1 &lt;&lt; v):                # v already visited
                    continue
                nmask = mask | (1 &lt;&lt; v)
                cand = dp[mask][u] + dist[u][v]
                if cand &lt; dp[nmask][v]:
                    dp[nmask][v] = cand

    full = (1 &lt;&lt; n) - 1
    return min(dp[full][u] + dist[u][0] for u in range(n))  # close the cycle
