C++Python <pre><code>/**
 * Convex hull — Andrew's monotone chain.
 *
 * Returns the vertices of the convex hull in counter-clockwise order.
 *   time:  O(n log n)   (dominated by the sort)
 *   space: O(n)
 * Collinear points on the hull edges are removed (strict `&lt;= 0` test).
 */
#include &lt;vector&gt;
#include &lt;algorithm&gt;
using namespace std;

struct P {
    long long x, y;
    bool operator&lt;(const P&amp; o) const {
        return x &lt; o.x || (x == o.x &amp;&amp; y &lt; o.y);
    }
};

// Cross product of OA x OB. &gt;0 left turn, &lt;0 right turn, =0 collinear.
long long cross(const P&amp; O, const P&amp; A, const P&amp; B) {
    return (A.x - O.x) * (B.y - O.y) - (A.y - O.y) * (B.x - O.x);
}

vector&lt;P&gt; convex_hull(vector&lt;P&gt; pts) {
    int n = pts.size();
    if (n &lt; 3) return pts;
    sort(pts.begin(), pts.end());

    vector&lt;P&gt; h(2 * n);
    int k = 0;
    // Lower hull.
    for (int i = 0; i &lt; n; i++) {
        while (k &gt;= 2 &amp;&amp; cross(h[k - 2], h[k - 1], pts[i]) &lt;= 0) k--;
        h[k++] = pts[i];
    }
    // Upper hull.
    for (int i = n - 2, t = k + 1; i &gt;= 0; i--) {
        while (k &gt;= t &amp;&amp; cross(h[k - 2], h[k - 1], pts[i]) &lt;= 0) k--;
        h[k++] = pts[i];
    }
    h.resize(k - 1);   // last point equals the first
    return h;
}
</code></pre> <pre><code>"""Convex hull — Andrew's monotone chain.

Returns the vertices of the convex hull in counter-clockwise order.
    time:  O(n log n)   (dominated by the sort)
    space: O(n)
Points are (x, y) tuples. Collinear points on the hull edges are removed.
"""


def cross(o, a, b):
    """Cross product OA x OB. &gt;0 left turn, &lt;0 right turn, =0 collinear."""
    return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])


def convex_hull(points):
    pts = sorted(set(points))
    if len(pts) &lt; 3:
        return pts

    lower = []
    for p in pts:
        while len(lower) &gt;= 2 and cross(lower[-2], lower[-1], p) &lt;= 0:
            lower.pop()
        lower.append(p)

    upper = []
    for p in reversed(pts):
        while len(upper) &gt;= 2 and cross(upper[-2], upper[-1], p) &lt;= 0:
            upper.pop()
        upper.append(p)

    # Concatenate, dropping the last point of each (it repeats the other's start).
    return lower[:-1] + upper[:-1]
