C++Python <pre><code>// Binary search on a sorted vector.
// Returns an index i with a[i] == target, or -1 if target is not present.
//   time:  O(log n)
//   space: O(1)
// Precondition: `a` is sorted in non-decreasing order.
#include &lt;vector&gt;
using namespace std;

int binary_search_idx(const vector&lt;int&gt;&amp; a, int target) {
    int lo = 0, hi = (int)a.size() - 1;
    while (lo &lt;= hi) {
        int mid = lo + (hi - lo) / 2;   // avoids overflow vs (lo + hi) / 2
        if (a[mid] == target) return mid;
        if (a[mid] &lt; target) lo = mid + 1;
        else hi = mid - 1;
    }
    return -1;
}
</code></pre> <pre><code>"""Binary search on a sorted list.

Returns an index i with a[i] == target, or -1 if target is not present.
    time:  O(log n)
    space: O(1)
Precondition: `a` is sorted in non-decreasing order.
"""


def binary_search(a, target):
    lo, hi = 0, len(a) - 1
    while lo &lt;= hi:
        mid = (lo + hi) // 2
        if a[mid] == target:
            return mid
        if a[mid] &lt; target:
            lo = mid + 1
        else:
            hi = mid - 1
    return -1
